using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Rendering;

namespace Sankofa.EditorTools
{
    /// <summary>
    /// Deterministic procedural meshes for the hearth: terrain, stones, logs, tree silhouettes and stars.
    /// Generated by the scene builder and saved as assets; the same seed always gives the same shape.
    /// </summary>
    public static class SankofaMeshes
    {
        // ---- noise ----

        static float Hash(int x, int y, int z, int seed)
        {
            unchecked
            {
                var h = (uint)(x * 374761393 + y * 668265263 + z * 1274126177 + seed * 1442695041);
                h = (h ^ (h >> 13)) * 1274126177u;
                h ^= h >> 16;
                return (h & 0xFFFFFF) / 16777215f;
            }
        }

        static float Smooth(float t) => t * t * (3f - 2f * t);

        /// <summary>Smooth lattice noise in 0..1.</summary>
        public static float Value(Vector3 p, int seed)
        {
            int x0 = Mathf.FloorToInt(p.x), y0 = Mathf.FloorToInt(p.y), z0 = Mathf.FloorToInt(p.z);
            float tx = Smooth(p.x - x0), ty = Smooth(p.y - y0), tz = Smooth(p.z - z0);
            float L(int dx, int dy, int dz) => Hash(x0 + dx, y0 + dy, z0 + dz, seed);
            var a = Mathf.Lerp(Mathf.Lerp(L(0, 0, 0), L(1, 0, 0), tx), Mathf.Lerp(L(0, 1, 0), L(1, 1, 0), tx), ty);
            var b = Mathf.Lerp(Mathf.Lerp(L(0, 0, 1), L(1, 0, 1), tx), Mathf.Lerp(L(0, 1, 1), L(1, 1, 1), tx), ty);
            return Mathf.Lerp(a, b, tz);
        }

        /// <summary>Fractal noise centred on zero, roughly −0.5..0.5.</summary>
        public static float Fbm(Vector3 p, int seed, int octaves = 4)
        {
            float sum = 0, amplitude = 1, total = 0;
            for (var o = 0; o < octaves; o++)
            {
                sum += (Value(p, seed + o * 31) - 0.5f) * amplitude;
                total += amplitude;
                p *= 2.03f;
                amplitude *= 0.5f;
            }
            return sum / total;
        }

        static Mesh Finish(Mesh mesh, string name)
        {
            mesh.name = name;
            mesh.RecalculateNormals();
            // Tangents follow UVs; meshes detailed in world space (terrain, grass) have none.
            if (mesh.uv != null && mesh.uv.Length == mesh.vertexCount) mesh.RecalculateTangents();
            mesh.RecalculateBounds();
            return mesh;
        }

        // ---- terrain ----

        /// <summary>
        /// A disc of ground centred on the fire: a shallow ash pit, a trodden clearing where the visitor sits,
        /// rolling ground beyond and low hills on the horizon. Fine near the hearth, coarse far away.
        /// Vertex colour carries a tint over the scanned ground and UV.x how burned the ground is; baking adds
        /// occlusion and fire and moon visibility later.
        /// </summary>
        public static Mesh Terrain(Vector3 fire, int seed)
        {
            const int segments = 160;
            var radii = new List<float>();
            for (var r = 0.035f; r < 3.4f; r += 0.035f) radii.Add(r);
            for (var r = 3.4f; r < 75f; r *= 1.12f) radii.Add(r);

            var vertices = new List<Vector3>();
            var colors = new List<Color>();
            var burn = new List<Vector2>();
            var triangles = new List<int>();

            void Add(float x, float z)
            {
                var d = new Vector2(x, z).magnitude;
                var world = new Vector3(fire.x + x, 0, fire.z + z);
                vertices.Add(new Vector3(world.x, Height(world, d, seed), world.z));
                colors.Add(GroundTint(world, d, seed));
                burn.Add(new Vector2(Burn(world, d, seed), 0));
            }

            Add(0, 0);
            foreach (var r in radii)
                for (var s = 0; s < segments; s++)
                {
                    var angle = s * Mathf.PI * 2f / segments;
                    Add(Mathf.Cos(angle) * r, Mathf.Sin(angle) * r);
                }

            for (var s = 0; s < segments; s++)
            {
                triangles.Add(0);
                triangles.Add(1 + (s + 1) % segments);
                triangles.Add(1 + s);
            }
            for (var ring = 0; ring < radii.Count - 1; ring++)
            {
                var inner = 1 + ring * segments;
                var outer = inner + segments;
                for (var s = 0; s < segments; s++)
                {
                    var n = (s + 1) % segments;
                    triangles.Add(inner + s);
                    triangles.Add(inner + n);
                    triangles.Add(outer + s);
                    triangles.Add(inner + n);
                    triangles.Add(outer + n);
                    triangles.Add(outer + s);
                }
            }

            var mesh = new Mesh { indexFormat = IndexFormat.UInt32 };
            mesh.SetVertices(vertices);
            mesh.SetColors(colors);
            mesh.SetUVs(0, burn);
            mesh.SetTriangles(triangles, 0);
            mesh.SetUVs(1, new List<Vector2>(new Vector2[vertices.Count]));
            // UV.x is a blend weight, not a texture coordinate; the ground shader projects its maps from above.
            return Finish(mesh, "Hearth terrain");
        }

        /// <summary>Ground height at a point, for placing things on the generated terrain.</summary>
        public static float GroundHeight(Vector3 world, Vector3 fire, int seed) =>
            Height(world, new Vector2(world.x - fire.x, world.z - fire.z).magnitude, seed);

        static float Height(Vector3 world, float fromFire, int seed)
        {
            var pit = -0.035f * (1f - Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(0.25f, 0.62f, fromFire)));
            var clearing = Fbm(world * 1.7f, seed, 3) * 0.02f;
            var rolling = Fbm(world * 0.18f, seed + 7, 4) * 1.1f * Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(4f, 11f, fromFire));
            var hills = (Fbm(world * 0.035f, seed + 13, 3) + 0.42f) * 9f * Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(22f, 60f, fromFire));
            return pit + clearing + rolling + hills;
        }

        /// <summary>A gentle tint over the scanned ground: trodden earth a little darker and warmer, patches, the distance darker.</summary>
        static Color GroundTint(Vector3 world, float fromFire, int seed)
        {
            var variation = 1f + Fbm(world * 0.9f, seed + 3, 3) * 0.3f;
            var patches = Fbm(world * 0.22f, seed + 5, 2);
            var trodden = new Color(0.82f, 0.74f, 0.66f);
            var wild = Color.Lerp(new Color(0.9f, 0.88f, 0.8f), new Color(0.68f, 0.68f, 0.6f), Mathf.Clamp01(patches * 2f + 0.5f));
            var far = new Color(0.5f, 0.5f, 0.46f);
            var c = Color.Lerp(trodden, wild, Mathf.InverseLerp(2.6f, 4.5f, fromFire));
            c = Color.Lerp(c, far, Mathf.InverseLerp(18f, 45f, fromFire));
            c *= variation;
            c.a = 1;
            return c;
        }

        /// <summary>How burned the ground is: fully inside the stone ring, fading out with a ragged edge.</summary>
        static float Burn(Vector3 world, float fromFire, int seed)
        {
            var ragged = Fbm(world * 4f, seed + 17, 2) * 0.25f;
            return 1f - Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(0.5f + ragged, 1.0f + ragged, fromFire));
        }

        // ---- stones ----

        /// <summary>A weathered stone: an icosphere displaced by noise with a flattened base.</summary>
        public static Mesh Stone(int seed, int subdivisions = 3, float roughness = 0.22f, float flatten = 0.35f)
        {
            Icosphere(subdivisions, out var vertices, out var triangles);
            var offset = new Vector3(seed * 1.31f, seed * 0.77f, seed * 2.13f);
            for (var i = 0; i < vertices.Count; i++)
            {
                var d = vertices[i];
                var r = 1f + Fbm(d * 1.4f + offset, seed, 3) * roughness * 2f + Fbm(d * 4.2f + offset, seed + 9, 2) * roughness * 0.5f;
                var p = d * r;
                if (p.y < -flatten) p.y = -flatten + (p.y + flatten) * 0.2f;
                vertices[i] = p;
            }
            var uvs = new List<Vector2>(vertices.Count);
            foreach (var v in vertices)
                uvs.Add(new Vector2(Mathf.Atan2(v.z, v.x) / (Mathf.PI * 2f) + 0.5f, v.y * 0.5f + 0.5f));
            var mesh = new Mesh();
            mesh.SetVertices(vertices);
            mesh.SetUVs(0, uvs);
            mesh.SetTriangles(triangles, 0);
            mesh.SetColors(Fill(vertices.Count, Color.white));
            mesh.SetUVs(1, new List<Vector2>(new Vector2[vertices.Count]));
            return Finish(mesh, "Stone " + seed);
        }

        static void Icosphere(int subdivisions, out List<Vector3> vertices, out List<int> triangles)
        {
            var t = (1f + Mathf.Sqrt(5f)) / 2f;
            vertices = new List<Vector3>
            {
                new Vector3(-1, t, 0), new Vector3(1, t, 0), new Vector3(-1, -t, 0), new Vector3(1, -t, 0),
                new Vector3(0, -1, t), new Vector3(0, 1, t), new Vector3(0, -1, -t), new Vector3(0, 1, -t),
                new Vector3(t, 0, -1), new Vector3(t, 0, 1), new Vector3(-t, 0, -1), new Vector3(-t, 0, 1),
            };
            for (var i = 0; i < vertices.Count; i++) vertices[i] = vertices[i].normalized;
            triangles = new List<int>
            {
                0, 11, 5, 0, 5, 1, 0, 1, 7, 0, 7, 10, 0, 10, 11, 1, 5, 9, 5, 11, 4, 11, 10, 2, 10, 7, 6, 7, 1, 8,
                3, 9, 4, 3, 4, 2, 3, 2, 6, 3, 6, 8, 3, 8, 9, 4, 9, 5, 2, 4, 11, 6, 2, 10, 8, 6, 7, 9, 8, 1,
            };
            for (var s = 0; s < subdivisions; s++)
            {
                var cache = new Dictionary<long, int>();
                var next = new List<int>(triangles.Count * 4);
                var verts = vertices;
                int Mid(int a, int b)
                {
                    var key = ((long)Math.Min(a, b) << 32) | (uint)Math.Max(a, b);
                    if (cache.TryGetValue(key, out var index)) return index;
                    verts.Add(((verts[a] + verts[b]) * 0.5f).normalized);
                    cache[key] = verts.Count - 1;
                    return verts.Count - 1;
                }
                for (var i = 0; i < triangles.Count; i += 3)
                {
                    int a = triangles[i], b = triangles[i + 1], c = triangles[i + 2];
                    int ab = Mid(a, b), bc = Mid(b, c), ca = Mid(c, a);
                    next.AddRange(new[] { a, ab, ca, b, bc, ab, c, ca, bc, ab, bc, ca });
                }
                triangles = next;
            }
        }

        // ---- logs and branches ----

        /// <summary>
        /// An irregular log along local Y with capped ends. UV x runs around the bark and y along its length,
        /// so bark detail stretches with the grain; caps get a radial UV for growth rings.
        /// </summary>
        public static Mesh Log(int seed, float length, float radius, float taper = 0.1f, float bend = 0.03f, int sides = 14, int segments = 10)
        {
            var vertices = new List<Vector3>();
            var uvs = new List<Vector2>();
            var triangles = new List<int>();
            var offset = new Vector3(seed * 0.73f, seed * 1.9f, 0);

            for (var j = 0; j <= segments; j++)
            {
                var v = (float)j / segments;
                var y = (v - 0.5f) * length;
                var centre = new Vector3(Mathf.Sin(v * Mathf.PI) * bend, y, Mathf.Sin(v * Mathf.PI * 1.3f + seed) * bend * 0.6f);
                for (var i = 0; i <= sides; i++)
                {
                    var u = (float)i / sides;
                    var angle = u * Mathf.PI * 2f;
                    var bumps = 1f + Fbm(new Vector3(Mathf.Cos(angle) * 1.2f, v * length * 2.5f, Mathf.Sin(angle) * 1.2f) + offset, seed, 3) * 0.28f;
                    var r = radius * (1f - taper * v) * bumps;
                    vertices.Add(centre + new Vector3(Mathf.Cos(angle) * r, 0, Mathf.Sin(angle) * r));
                    uvs.Add(new Vector2(u, v * length));
                }
            }
            for (var j = 0; j < segments; j++)
                for (var i = 0; i < sides; i++)
                {
                    var a = j * (sides + 1) + i;
                    var b = a + sides + 1;
                    // Unity treats clockwise as front-facing; this order puts (p1 − p0) × (p2 − p0) outward.
                    triangles.AddRange(new[] { a, b, a + 1, a + 1, b, b + 1 });
                }

            foreach (var end in new[] { 0, segments })
            {
                var ringStart = end * (sides + 1);
                var centre = Vector3.zero;
                for (var i = 0; i < sides; i++) centre += vertices[ringStart + i];
                centre /= sides;
                var top = end == segments;
                var c = vertices.Count;
                vertices.Add(centre);
                uvs.Add(new Vector2(0.5f, 0.5f));
                for (var i = 0; i <= sides; i++)
                {
                    var angle = (float)i / sides * Mathf.PI * 2f;
                    vertices.Add(vertices[ringStart + i]);
                    uvs.Add(new Vector2(0.5f + Mathf.Cos(angle) * 0.5f, 0.5f + Mathf.Sin(angle) * 0.5f));
                }
                for (var i = 0; i < sides; i++)
                    triangles.AddRange(top ? new[] { c, c + 1 + i + 1, c + 1 + i } : new[] { c, c + 1 + i, c + 1 + i + 1 });
            }

            var mesh = new Mesh();
            mesh.SetVertices(vertices);
            mesh.SetUVs(0, uvs);
            mesh.SetTriangles(triangles, 0);
            mesh.SetColors(Fill(vertices.Count, Color.white));
            mesh.SetUVs(1, new List<Vector2>(new Vector2[vertices.Count]));
            return Finish(mesh, "Log " + seed);
        }

        // ---- tree silhouettes ----

        /// <summary>A trunk with a few rising branches, and clustered canopy masses at their ends.</summary>
        public static void Tree(int seed, float height, out Mesh trunk, out Mesh canopy)
        {
            var random = new System.Random(seed);
            float R(float a, float b) => a + (float)random.NextDouble() * (b - a);
            var trunkParts = new List<CombineInstance>();
            var canopyParts = new List<CombineInstance>();

            var trunkHeight = height * R(0.45f, 0.6f);
            var trunkRadius = height * 0.045f;
            var trunkMesh = Log(seed, trunkHeight, trunkRadius, 0.35f, height * 0.02f, 9, 6);
            trunkParts.Add(new CombineInstance { mesh = trunkMesh, transform = Matrix4x4.Translate(new Vector3(0, trunkHeight * 0.5f, 0)) });

            var branches = 3 + random.Next(3);
            for (var b = 0; b < branches; b++)
            {
                var yaw = b * 360f / branches + R(-25f, 25f);
                var tilt = R(18f, 38f);
                var length = height * R(0.24f, 0.36f);
                var rotation = Quaternion.Euler(0, yaw, 0) * Quaternion.Euler(tilt, 0, 0);
                var start = new Vector3(0, trunkHeight * R(0.75f, 0.98f), 0);
                var branch = Log(seed * 10 + b, length, trunkRadius * 0.5f, 0.6f, length * 0.04f, 7, 4);
                trunkParts.Add(new CombineInstance { mesh = branch, transform = Matrix4x4.TRS(start + rotation * (Vector3.up * length * 0.5f), rotation, Vector3.one) });
                var tip = start + rotation * (Vector3.up * length);
                var blobs = 2 + random.Next(3);
                for (var k = 0; k < blobs; k++)
                {
                    var size = height * R(0.14f, 0.22f);
                    var blob = Stone(seed * 100 + b * 10 + k, 2, 0.3f, 10f);
                    var at = tip + new Vector3(R(-0.5f, 0.5f), R(-0.2f, 0.6f), R(-0.5f, 0.5f)) * size;
                    canopyParts.Add(new CombineInstance { mesh = blob, transform = Matrix4x4.TRS(at, Quaternion.Euler(R(0, 360), R(0, 360), 0), new Vector3(size * 1.2f, size * R(0.9f, 1.15f), size * 1.15f)) });
                }
            }
            trunk = Combine(trunkParts, "Tree trunk " + seed);
            canopy = Combine(canopyParts, "Tree canopy " + seed);
        }

        static Mesh Combine(List<CombineInstance> parts, string name)
        {
            var mesh = new Mesh { indexFormat = IndexFormat.UInt32 };
            mesh.CombineMeshes(parts.ToArray(), true, true);
            var count = mesh.vertexCount;
            mesh.SetColors(Fill(count, Color.white));
            mesh.SetUVs(1, new List<Vector2>(new Vector2[count]));
            return Finish(mesh, name);
        }

        // ---- grass ----

        /// <summary>
        /// Tufts of curved blades scattered through an annulus around the fire, avoiding the visitor's seat.
        /// Colour runs from a dark base to a pale tip; alpha darkens the base like occlusion. Fire visibility is 1.
        /// </summary>
        public static Mesh Grass(Vector3 fire, Vector3 seat, int seed, int tufts, float inner, float outer, System.Func<Vector3, float> height)
        {
            var random = new System.Random(seed);
            float R(float a, float b) => a + (float)random.NextDouble() * (b - a);
            var vertices = new List<Vector3>();
            var colors = new List<Color>();
            var heights = new List<Vector2>();
            var bake = new List<Vector2>();
            var triangles = new List<int>();
            var placed = 0;
            for (var attempt = 0; placed < tufts && attempt < tufts * 20; attempt++)
            {
                var angle = R(0, Mathf.PI * 2f);
                var radius = Mathf.Sqrt(R(inner * inner, outer * outer));
                var at = fire + new Vector3(Mathf.Cos(angle) * radius, 0, Mathf.Sin(angle) * radius);
                if (new Vector2(at.x - seat.x, at.z - seat.z).magnitude < 1.1f) continue;
                if (Value(at * 0.6f, seed) < 0.42f) continue; // clumps, not an even lawn
                at.y = height(at);
                placed++;
                var blades = 5 + random.Next(5);
                var tuftHeight = R(0.12f, 0.32f);
                // Each tuft its own shade between dry straw, olive and grey-green.
                var hue = (float)random.NextDouble();
                var baseTint = Color.Lerp(new Color(0.15f, 0.13f, 0.08f), new Color(0.1f, 0.12f, 0.08f), hue);
                var tipTint = Color.Lerp(Color.Lerp(new Color(0.46f, 0.4f, 0.22f), new Color(0.32f, 0.36f, 0.2f), hue), new Color(0.38f, 0.37f, 0.3f), R(0f, 0.4f));
                for (var b = 0; b < blades; b++)
                {
                    var yaw = R(0, Mathf.PI * 2f);
                    var lean = R(0.1f, 0.5f);
                    var h = tuftHeight * R(0.6f, 1.1f);
                    var width = R(0.008f, 0.014f);
                    var root = at + new Vector3(R(-0.04f, 0.04f), 0, R(-0.04f, 0.04f));
                    var outward = new Vector3(Mathf.Cos(yaw), 0, Mathf.Sin(yaw));
                    var side = new Vector3(-outward.z, 0, outward.x) * width;
                    var start = vertices.Count;
                    for (var k = 0; k <= 2; k++)
                    {
                        var f = k / 3f;
                        var p = root + Vector3.up * (h * f) + outward * (lean * h * f * f);
                        var w = 1f - f * 0.6f;
                        vertices.Add(p - side * w);
                        vertices.Add(p + side * w);
                        var tint = Color.Lerp(baseTint, tipTint, f);
                        tint.a = Mathf.Lerp(0.45f, 1f, f);
                        colors.Add(tint);
                        colors.Add(tint);
                        heights.Add(new Vector2(0, f));
                        heights.Add(new Vector2(1, f));
                        bake.Add(new Vector2(1, 1));
                        bake.Add(new Vector2(1, 1));
                    }
                    vertices.Add(root + Vector3.up * h + outward * (lean * h));
                    var tip = tipTint * 1.08f;
                    tip.a = 1f;
                    colors.Add(tip);
                    heights.Add(new Vector2(0.5f, 1f));
                    bake.Add(new Vector2(1, 1));
                    for (var k = 0; k < 2; k++)
                    {
                        var a = start + k * 2;
                        triangles.AddRange(new[] { a, a + 2, a + 1, a + 1, a + 2, a + 3 });
                    }
                    triangles.AddRange(new[] { start + 4, start + 6, start + 5 });
                }
            }
            var mesh = new Mesh { indexFormat = IndexFormat.UInt32 };
            mesh.SetVertices(vertices);
            mesh.SetColors(colors);
            mesh.SetUVs(0, heights);
            mesh.SetUVs(1, bake);
            mesh.SetTriangles(triangles, 0);
            return Finish(mesh, "Grass");
        }

        // ---- sky ----

        /// <summary>
        /// Stars as tiny camera-facing quads on a dome. Each quad's corners share one centre; the shader spreads them.
        /// UV holds the corner, UV2 the size and a twinkle phase, colour the tint and brightness.
        /// </summary>
        public static Mesh Stars(int count, int seed, float radius)
        {
            var random = new System.Random(seed);
            var vertices = new List<Vector3>(count * 4);
            var corners = new List<Vector2>(count * 4);
            var data = new List<Vector2>(count * 4);
            var colors = new List<Color>(count * 4);
            var triangles = new List<int>(count * 6);
            var corner = new[] { new Vector2(-1, -1), new Vector2(1, -1), new Vector2(1, 1), new Vector2(-1, 1) };
            for (var s = 0; s < count; s++)
            {
                Vector3 dir;
                do dir = new Vector3((float)random.NextDouble() * 2 - 1, (float)random.NextDouble(), (float)random.NextDouble() * 2 - 1);
                while (dir.sqrMagnitude > 1 || dir.sqrMagnitude < 0.01f);
                dir.Normalize();
                if (dir.y < 0.04f) continue;
                var magnitude = Mathf.Pow((float)random.NextDouble(), 5f);
                var brightness = 0.25f + magnitude * 2.2f;
                var size = radius * (0.0018f + magnitude * 0.0032f);
                var warmth = (float)random.NextDouble();
                var tint = Color.Lerp(new Color(0.78f, 0.85f, 1f), new Color(1f, 0.9f, 0.76f), warmth) * brightness;
                tint.a = 1;
                var phase = (float)random.NextDouble() * 6.283f;
                var start = vertices.Count;
                for (var k = 0; k < 4; k++)
                {
                    vertices.Add(dir * radius);
                    corners.Add(corner[k]);
                    data.Add(new Vector2(size, phase));
                    colors.Add(tint);
                }
                triangles.AddRange(new[] { start, start + 2, start + 1, start, start + 3, start + 2 });
            }
            var mesh = new Mesh { name = "Stars", indexFormat = IndexFormat.UInt32 };
            mesh.SetVertices(vertices);
            mesh.SetUVs(0, corners);
            mesh.SetUVs(1, data);
            mesh.SetColors(colors);
            mesh.SetTriangles(triangles, 0);
            mesh.bounds = new Bounds(Vector3.zero, Vector3.one * radius * 2.2f);
            return mesh;
        }

        static List<Color> Fill(int count, Color c)
        {
            var list = new List<Color>(count);
            for (var i = 0; i < count; i++) list.Add(c);
            return list;
        }
    }
}
